'use client';
import Link from 'next/link';
import {createBrowserSupabaseClient} from '@/lib/supabase/client';
import {useEffect,useState} from 'react';
import {trustOperation,type TrustWorkspace} from '@/lib/repositories/businessTrustRepository';
import {loadCalendar,saveCalendarEvent} from '@/lib/repositories/vendorCalendarRepository';
import {localDate,todayIn,shiftDate,onDay,overlap,manualEntry,type CalendarEntry,type ManualEvent} from '@/lib/vendor-calendar/model';
import {EventEditor} from './EventEditor';
const button='rounded-lg border ui-border px-3 py-2 text-sm hover:bg-neutral-100 focus-visible:outline-2';
export function CalendarWorkspace({initial,compact=false}:{initial?:string;compact?:boolean}){
 const [businesses,setBusinesses]=useState<TrustWorkspace['businesses']>([]),[id,setId]=useState(initial||''),[error,setError]=useState(''),[loading,setLoading]=useState(true);
 useEffect(()=>{let live=true;const {data:{subscription}}=createBrowserSupabaseClient().auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){live=false;setBusinesses([]);setId('');setError('Sign in to view your private calendar.');setLoading(false);}});trustOperation<TrustWorkspace>('mine').then(m=>{if(!live)return;const rows=m.businesses.filter(b=>m.memberships.some(r=>r.vendor_id===b.id&&r.profile_id===m.actor_id&&r.status==='active'&&['owner','admin','manager'].includes(r.role))||(b.applicant_id===m.actor_id&&!b.owner_id&&b.approval_status==='pending'&&['pending','needs_more_information'].includes(b.verification_status||'')));setBusinesses(rows);setId(old=>rows.some(b=>b.id===old)?old:rows.length===1?rows[0].id:'');}).catch(e=>{if(live)setError(e.message);}).finally(()=>{if(live)setLoading(false);});return()=>{live=false;subscription.unsubscribe();};},[]);
 const [dirty,setDirty]=useState(false);
 return <section className="space-y-5"><header className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm ui-muted">Vendor Hub</p><h1 className="text-2xl font-semibold">{compact?'Upcoming Events':'Calendar'}</h1></div><Link className={button} href={compact?'/vendor/calendar':'/vendor/dashboard'}>{compact?'Open Calendar':'Vendor dashboard'}</Link></header>
 {error&&<p role="alert">{error} <Link href="/auth/login?next=%2Fvendor%2Fcalendar">Sign in</Link></p>}{loading?<p>Loading businesses…</p>:<label className="grid max-w-lg gap-2 text-sm">Business and branch<select className="hub-input" value={id} onChange={e=>{if(!dirty||window.confirm('Discard unsaved event changes?')){setDirty(false);setId(e.target.value);if(!compact){const url=new URL(window.location.href);if(e.target.value)url.searchParams.set('business',e.target.value);else url.searchParams.delete('business');window.history.replaceState(null,'',url);}}}}><option value="">Select a business</option>{businesses.map(b=><option key={b.id} value={b.id}>{b.business_name} · {b.location_name||b.service_area_city}</option>)}</select></label>}
 {!loading&&!error&&!businesses.length&&<p>No editable businesses yet. <Link className="underline" href="/vendor/onboarding">Find or create a business</Link></p>}
 {!loading&&businesses.some(b=>b.id===id)&&<BusinessCalendar key={id} id={id} compact={compact} onDirty={setDirty}/>}</section>;
}
function BusinessCalendar({id,compact,onDirty}:{id:string;compact:boolean;onDirty:(v:boolean)=>void}){
 const [data,setData]=useState<Awaited<ReturnType<typeof loadCalendar>>|null>(null),[error,setError]=useState(''),[notice,setNotice]=useState(''),[revision,setRevision]=useState(0);
 const [date,setDate]=useState(localDate()),[view,setView]=useState('Month'),[zone,setZone]=useState(''),[selected,setSelected]=useState<CalendarEntry|null>(null),[draft,setDraft]=useState<ManualEvent|null>(null),[dirty,setDirty]=useState(false);
 useEffect(()=>{let live=true;loadCalendar(id).then(rows=>{if(live){setData(rows);setError('');}}).catch(e=>{if(live)setError(e.message);});return()=>{live=false;};},[id,revision]);
 useEffect(()=>{if(!dirty)return;const handler=(e:BeforeUnloadEvent)=>{e.preventDefault();e.returnValue='';};window.addEventListener('beforeunload',handler);return()=>window.removeEventListener('beforeunload',handler);},[dirty]);
 function mark(value:boolean){setDirty(value);onDirty(value);}
 function leave(action:()=>void){if(dirty&&!window.confirm('Discard unsaved event changes?'))return;mark(false);action();}
 function add(){leave(()=>{setSelected(null);setDraft({id:crypto.randomUUID(),vendor_id:id,name:'',date,end_date:date,start_time:'',end_time:'',timezone:zone,status:'Tentative',event_type:'',client_name:'',client_contact:'',location:'',service_id:null,notes:'',tasks:[],version:0,created_at:'',updated_at:'',created_by:'',updated_by:''});});}
 const entries=data?.entries||[];
 const warnings=(entry:CalendarEntry)=>{
 const result=entries.filter(e=>e.id!==entry.id&&overlap(entry,e)).map(e=>`Time overlaps ${e.name}. Check your team's capacity.`);
 for(const a of data?.availability||[])if(a.status!=='available'&&overlap(entry,{id:a.id,name:a.status,date:a.date,end_date:a.end_time<=a.start_time?shiftDate(a.date,1):a.date,start_time:a.start_time,end_time:a.end_time,status:a.status,timezone:entry.timezone,source:'External Event',location:'',notes:'',service:''}))result.push(`Overlaps ${a.status} availability on ${a.date}.`);
 if(entry.source==='ARIVVIO'&&!entry.timezone)result.push('Booking timezone is not recorded. Confirm local scheduling details.');return result;};
 const first=date.slice(0,7)+'-01',offset=new Date(first+'T12:00:00').getDay(),cells=Array.from({length:42},(_,i)=>shiftDate(first,i-offset));
 const shown=compact?entries.filter(e=>e.status.toLowerCase()!=='cancelled'&&(!e.date||(e.end_date||e.date)>=todayIn(zone))).slice(0,5):view==='Agenda'?entries.filter(e=>!e.date||(e.end_date||e.date)>=date):entries.filter(e=>onDay(e,date));
 function move(delta:number){leave(()=>{if(view==='Month'){const d=new Date(first+'T12:00:00');d.setMonth(d.getMonth()+delta);setDate(localDate(d));}else setDate(shiftDate(date,delta));});}
 function open(e:CalendarEntry){leave(()=>{setDraft(null);setSelected(e);});}
 return <div className="space-y-4">{error&&<p role="alert">{error} <button className={button} onClick={()=>setRevision(v=>v+1)}>Retry</button></p>}{notice&&<p role="status">{notice}</p>}{!data&&!error&&<p>Loading schedule…</p>}
 {data?.vacation&&<p className="rounded-lg bg-amber-50 p-3 text-amber-900">Vacation mode is on. Existing availability settings remain in effect.</p>}
 {!compact&&<><div className="flex flex-wrap items-end justify-between gap-3"><div className="flex flex-wrap gap-2">{['Month','Day','Agenda'].map(v=><button key={v} aria-pressed={view===v} className={button+(view===v?' bg-neutral-100 font-semibold':'')} onClick={()=>leave(()=>setView(v))}>{v}</button>)}</div><button className={button} onClick={()=>leave(()=>{setSelected(null);setRevision(v=>v+1);})}>Refresh</button><button className="hub-primary" onClick={add} disabled={!data}>Add Event</button></div>
 <div className="flex flex-wrap items-center gap-2"><button aria-label="Previous date" className={button} onClick={()=>move(-1)}>←</button><button className={button} onClick={()=>leave(()=>setDate(todayIn(zone)))}>Today</button><button aria-label="Next date" className={button} onClick={()=>move(1)}>→</button><label className="text-sm">Selected date <input className={button} type="date" value={date} onChange={e=>{if(e.target.value)leave(()=>setDate(e.target.value));}}/></label><span className="text-sm ui-muted">{zone||'Local dates as entered'}</span></div>
 {view==='Month'&&<div className="overflow-hidden rounded-xl border ui-border"><div className="grid grid-cols-7 bg-neutral-50 text-center text-xs text-neutral-700">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=><span className="py-2" key={d}>{d}</span>)}</div><div className="grid grid-cols-7">{cells.map(day=>{const list=entries.filter(e=>onDay(e,day));return <button key={day} aria-label={`${day}, ${list.length} events. Open day schedule`} aria-pressed={date===day} onClick={()=>leave(()=>{setDate(day);setView('Day');})} className={`min-h-16 border ui-border p-1 text-left sm:min-h-28 sm:p-2 ${day===date?'bg-blue-50 text-neutral-900':day.slice(0,7)!==date.slice(0,7)?'opacity-50':''}`}><span className="text-sm">{Number(day.slice(-2))}</span>{list.slice(0,2).map(e=><span key={e.id} className="mt-1 hidden truncate text-xs sm:block">{e.start_time?.slice(0,5)||'Time needed'} {e.name}</span>)}{!!list.length&&<span className="block text-[10px] sm:text-xs">{list.length} event{list.length===1?'':'s'}</span>}</button>;})}</div></div>}
 </>}
 {draft&&<EventEditor key={draft.id} initial={draft} services={data?.services||[]} warnings={warnings(manualEntry(draft))} onChange={d=>{setDraft(d);mark(true);}} onCancel={()=>leave(()=>setDraft(null))} onSave={async()=>{const saved=await saveCalendarEvent(draft,draft.version===0);mark(false);setZone(saved.timezone);setDraft(null);setSelected(manualEntry(saved,data?.services.find(s=>s.id===saved.service_id)?.service_name));setNotice('Event saved.');setRevision(v=>v+1);}}/>}
 {selected&&!draft&&<section aria-label="Event details" className="rounded-xl border ui-border ui-surface p-5"><div className="flex justify-between gap-4"><h2 className="text-xl font-semibold">{selected.name}</h2><button className={button} onClick={()=>setSelected(null)}>Close details</button></div><p className="mt-2">{selected.source} · {selected.status}</p><p>{selected.date||'Date needed'} {selected.start_time?.slice(0,5)||'Start time needed'} to {selected.end_time?.slice(0,5)||'End time needed'}{selected.end_date!==selected.date?' · Ends '+selected.end_date:''} {selected.timezone||'· Timezone not recorded'}</p><p className="mt-3">{selected.location}</p><p>{selected.service}</p><p className="whitespace-pre-wrap py-3">{selected.notes}</p>{selected.manual?<><p>{selected.manual.client_name}</p><p>{selected.manual.client_contact}</p>{selected.manual.tasks.map((t,i)=><p key={i}>{t.done?'✓':'○'} {t.title}</p>)}<button className={button+' mt-4'} onClick={()=>setDraft(selected.manual!)}>Edit event and tasks</button></>:<Link className={button} href={'/bookings/'+selected.id}>Open ARIVVIO booking</Link>}{warnings(selected).map(w=><p key={w} className="mt-2 text-sm text-amber-800">{w}</p>)}</section>}
 <section className="rounded-xl border ui-border ui-surface p-4"><h2 className="mb-3 font-semibold">{compact?'Next on your schedule':view==='Agenda'?'Agenda from '+date:'Schedule for '+date}</h2>{!shown.length&&data&&<div className="py-6"><p>No events scheduled yet. Add an event from your existing business or manage your upcoming ARIVVIO bookings here.</p>{compact?<Link className={button+' mt-3 inline-block'} href={'/vendor/calendar?business='+id}>Add Event</Link>:<button className={button+' mt-3'} onClick={add}>Add Event</button>}</div>}{shown.map(e=><button key={e.id} className="my-2 block w-full rounded-lg border ui-border p-3 text-left hover:bg-neutral-50 hover:text-neutral-900" onClick={()=>open(e)}><span className="flex flex-wrap justify-between gap-2"><strong>{e.name}</strong><span className={`rounded-full px-2 py-1 text-xs ${e.status.toLowerCase()==='cancelled'?'bg-neutral-100 text-neutral-600':e.status.toLowerCase()==='confirmed'?'bg-emerald-50 text-emerald-900':e.status.toLowerCase()==='completed'?'bg-blue-50 text-blue-900':'bg-amber-50 text-amber-900'}`}>{e.source} · {e.status}</span></span><span className="mt-2 block text-sm">{e.date||'Date needed'} · {e.start_time?.slice(0,5)||'Time needed'}{e.end_time?' – '+e.end_time.slice(0,5):''}{e.end_date&&e.end_date!==e.date?' · Ends '+e.end_date:''} {e.timezone}</span>{warnings(e).length>0&&<span className="block text-xs text-amber-800">Schedule overlap. Review capacity.</span>}</button>)}
 {!compact&&(data?.availability||[]).filter(a=>a.date===date).map(a=><p key={a.id} className="mt-2 rounded-lg border border-dashed p-3 text-sm">Availability: {a.status} · {a.start_time.slice(0,5)} to {a.end_time.slice(0,5)}</p>)}
 </section>{!compact&&<p className="text-xs ui-muted">Overlaps are advisory. External events do not change public availability or send messages. ARIVVIO bookings with missing schedule details need review. <Link className="underline" href="/vendor/dashboard">Manage availability in Vendor Hub</Link></p>}</div>;
}
